          {
            "type": "edge_case_tests",
            "description": "Cover boundary conditions and corner cases",
            "coverage": "Null values, empty inputs, limits, error conditions"
          }
        ]
      },
      "test_structure_template": {
        "description": "Language-agnostic test structure",
        "template": [
          "describe('BUG-{ID}: {description}', () => {",
          "  test('reproduces original bug', () => {",
          "    // This test demonstrates the bug existed",
          "    // Should fail before fix, pass after",
          "  });",
          "",
          "  test('verifies fix resolves issue', () => {",
          "    // This test proves correct behavior after fix",
          "  });",
          "",
          "  test('handles edge case: {case}', () => {",
          "    // Additional coverage for related scenarios",
          "  });",
          "});"
        ]
      },
      "validation_steps": [
        {
          "step": "Run full test suite",
          "commands": {
            "javascript": "npm test",
            "python": "pytest",
            "go": "go test ./...",
            "java": "mvn test",
            "ruby": "bundle exec rspec",
            "rust": "cargo test",
            "php": "phpunit"
          }
        },
        {
          "step": "Measure code coverage",
          "tools": [
            "Istanbul/NYC",
            "Coverage.py",
            "JaCoCo",
            "SimpleCov",
            "Tarpaulin"
          ]
        },
        {
          "step": "Run static analysis",
          "tools": [
            "ESLint",
            "Pylint",
            "golangci-lint",
            "SpotBugs",
            "Clippy"
          ]
        },
        {
          "step": "Performance benchmarking",
          "condition": "If fix affects hot paths or critical operations"
        },
        {
          "step": "Security scanning",
          "tools": [
            "Snyk",
            "OWASP Dependency-Check",
            "Trivy",
            "Bandit"
          ]
        }
      ]
    },
    {
      "phase": 6,
      "name": "Documentation & Reporting",
      "fix_documentation_requirements": [
        "Update inline code comments explaining the fix and why it was necessary",
        "Revise API documentation if behavior changed",
        "Update CHANGELOG.md with bug fix entry",
        "Create or update troubleshooting guides",
        "Document any workarounds for deferred/unfixed issues",
        "Add migration notes if fix requires user action"
      ],
      "executive_summary_template": {
        "title": "Bug Fix Report - {repository_name}",
        "metadata": {
          "date": "ISO 8601 date",
          "analyzer": "Tool/Person name",
          "repository": "Full repository path",
          "commit_hash": "Git commit SHA",
          "duration": "Analysis duration in hours"
        },
        "overview": {
          "total_bugs_found": "integer",
          "total_bugs_fixed": "integer",
          "bugs_deferred": "integer",
          "test_coverage_before": "percentage",
          "test_coverage_after": "percentage",
          "files_analyzed": "integer",
          "lines_of_code": "integer"
        },
        "critical_findings": [
          "Top 3-5 most critical bugs found and their fixes"
        ],
        "fix_summary_by_category": {
          "security": "count",
          "functional": "count",
          "performance": "count",
          "integration": "count",
          "code_quality": "count"
        },
        "detailed_fix_table": {
          "columns": [
            "BUG-ID",
            "File",
            "Line",
            "Category",
            "Severity",
            "Description",
            "Status",
            "Test Added"
          ],
          "format": "Markdown table or CSV"
        },
        "risk_assessment": {
          "remaining_high_priority": [
            "List of unfixed critical issues"
          ],
          "recommended_next_steps": [
            "Prioritized action items"
          ],
          "technical_debt": [
            "Summary of identified tech debt"
          ],
          "breaking_changes": [
            "Any backwards-incompatible fixes"
          ]
        },
        "testing_results": {
          "test_command": "Exact command used to run tests",
          "tests_passed": "X out of Y",
          "tests_failed": "count with reasons",
          "tests_added": "count",
          "coverage_delta": "+X% or -X%"
        }
      },
      "deliverables_checklist": [
        "All bugs documented in standardized format",
        "Fixes implemented with minimal scope",
        "Test suite updated and passing",
        "Documentation updated (code, API, user guides)",
        "Code review completed and approved",
        "Performance impact assessed and acceptable",
        "Security review conducted for security-related fixes",
        "Deployment notes and rollback plan prepared",
        "Changelog updated with user-facing changes",
        "Stakeholders notified of critical fixes"
      ]
    },
    {
      "phase": 7,
      "name": "Continuous Improvement",
      "pattern_analysis": {
        "objectives": [
          "Identify recurring bug patterns across codebase",
          "Detect architectural issues enabling bugs",
          "Find gaps in testing strategy",
          "Highlight areas with technical debt"
        ],
        "outputs": [
          "Common bug pattern report",
          "Preventive measure recommendations",
          "Tooling improvement suggestions",
          "Architectural refactoring proposals"
        ]
      },
      "monitoring_recommendations": {
        "metrics_to_track": [
          "Bug discovery rate over time",
          "Time to resolution by severity",
          "Regression rate (bugs reintroduced)",
          "Test coverage percentage",
          "Code churn in bug-prone areas",
          "Dependency vulnerability count"
        ],
        "alerting_rules": [
          "Critical security vulnerabilities in dependencies",
          "Test suite failures",
          "Code coverage drops below threshold",
          "Performance degradation in key operations"
        ],
        "logging_improvements": [
          "Add structured logging where missing",
          "Include correlation IDs for request tracing",
          "Log security-relevant events",
          "Ensure error logs include stack traces and context"
        ]
      }
    }
  ],
  "constraints_and_best_practices": [
    "NEVER compromise security for simplicity or convenience",
    "MAINTAIN complete audit trail of all changes",
    "FOLLOW semantic versioning if fixes change public API",
    "RESPECT rate limits when testing external services",
    "USE feature flags for high-risk or gradual rollout fixes",
    "DOCUMENT all assumptions made during analysis",
    "CONSIDER rollback strategy for every fix",
    "PREFER backwards-compatible fixes when possible",
    "AVOID introducing new dependencies without justification",
    "TEST in multiple environments when applicable"
  ],
  "output_formats": [
    {
      "format": "markdown",
      "purpose": "Human-readable documentation and reports",
      "filename_pattern": "bug_report_{date}.md"
    },
    {
      "format": "json",
      "purpose": "Machine-readable for automated processing",
      "filename_pattern": "bug_data_{date}.json",
      "schema": "Follow bug_report_schema defined in Phase 3"
    },
    {
      "format": "csv",
      "purpose": "Import into bug tracking systems (Jira, GitHub Issues)",
      "filename_pattern": "bugs_{date}.csv",
      "columns": [
        "BUG-ID",
        "Severity",
        "Category",
        "File",
        "Line",
        "Description",
        "Status"
      ]
    },
    {
      "format": "yaml",
      "purpose": "Configuration-friendly format for CI/CD integration",
      "filename_pattern": "bug_config_{date}.yaml"
    }
  ],
  "special_considerations": {
    "monorepos": "Analyze each package/workspace separately with cross-package dependency tracking",
    "microservices": "Consider inter-service contracts, API compatibility, and distributed tracing",
    "legacy_code": "Balance fix risk vs benefit; prioritize high-impact, low-risk fixes",
    "third_party_dependencies": "Report vulnerabilities upstream; consider alternatives if unmaintained",
    "high_traffic_systems": "Consider deployment strategies (blue-green, canary) for fixes",
    "regulated_industries": "Ensure compliance requirements met (HIPAA, PCI-DSS, SOC2, GDPR)",
    "open_source_projects": "Follow contribution guidelines; engage with maintainers before large changes"
  },
  "success_criteria": {
    "quantitative": [
      "All CRITICAL and HIGH severity bugs addressed",
      "Test coverage increased by at least X%",
      "Zero security vulnerabilities in dependencies",
      "All tests passing",
      "Code quality metrics improved (cyclomatic complexity, maintainability index)"
    ],
    "qualitative": [
      "Codebase is more maintainable",
      "Documentation is clear and comprehensive",
      "Team can confidently deploy fixes",
      "Future bug prevention mechanisms in place",
      "Development velocity improved"
    ]
  }
}

vi_prompt:
{
  "task": "comprehensive_repository_analysis",
  "objective": "Tiến hành phân tích toàn diện và triệt để toàn bộ kho mã nguồn (codebase) nhằm phát hiện, phân loại ưu tiên, khắc phục và lập tài liệu cho TẤT CẢ các lỗi có thể kiểm chứng, lỗ hổng bảo mật và sự cố nghiêm trọng trên mọi ngăn xếp công nghệ",
  "analysis_phases": [
    {
      "phase": 1,
      "name": "Khám phá & Lập bản đồ Kho mã nguồn (Repository Discovery & Mapping)",
      "steps": [
        {
          "step": "1.1",
          "title": "Phân tích Kiến trúc & Cấu trúc Thư mục",
          "actions": [
            "Lập bản đồ toàn bộ cấu trúc thư mục (src/, lib/, tests/, docs/, config/, scripts/, build/, deploy/)",
            "Xác định toàn bộ các ngăn xếp công nghệ (tech stacks) và framework đang sử dụng",
            "Phân tích các tệp quản lý phụ thuộc (package.json, requirements.txt, go.mod, pom.xml, Gemfile, Cargo.toml, composer.json)",
            "Ghi nhận tài liệu về các điểm khởi chạy (entry points), luồng thực thi chính và ranh giới module",
            "Phân tích hệ thống build (Webpack, Gradle, Maven, Make, CMake)",
            "Rà soát cấu hình CI/CD (GitHub Actions, GitLab CI, Jenkins, CircleCI)",
            "Kiểm tra tài liệu hiện có (README, CONTRIBUTING, thông số API, sơ đồ kiến trúc)"
          ]
        },
        {
          "step": "1.2",
          "title": "Kiểm kê Môi trường Phát triển",
          "actions": [
            "Xác định các framework kiểm thử (Jest, Mocha, pytest, PHPUnit, Go test, JUnit, RSpec, xUnit)",
            "Xem xét cấu hình linter/formatter (ESLint, Prettier, Black, Flake8, RuboCop, golangci-lint, Checkstyle)",
            "Quét tìm các điểm đánh dấu sự cố nội dòng (TODO, FIXME, HACK, XXX, BUG, NOTE)",
            "Phân tích lịch sử git để phát hiện các mẫu lỗi lặp lại và các bản vá nóng (hotfixes) gần đây",
            "Trích xuất báo cáo và số liệu độ bao phủ kiểm thử (test coverage) hiện tại",
            "Xác định các công cụ phân tích mã tĩnh đang sử dụng (SonarQube, CodeClimate, v.v.)"
          ]
        }
      ]
    },
    {
      "phase": 2,
      "name": "Phát hiện Lỗi Hệ thống (Systematic Bug Discovery)",
      "bug_categories": [
        {
          "category": "NGHIÊM TRỌNG (CRITICAL)",
          "severity": "P0",
          "types": [
            "Lỗ hổng tiêm mã SQL (SQL Injection)",
            "Lỗi tấn công kịch bản chéo trang (Cross-Site Scripting - XSS)",
            "Lỗ hổng làm giả yêu cầu chéo trang (Cross-Site Request Forgery - CSRF)",
            "Bỏ qua cơ chế xác thực / phân quyền (Auth bypass)",
            "Rủi ro thực thi mã từ xa (Remote Code Execution - RCE)",
            "Hỏng hóc dữ liệu hoặc mất mát dữ liệu vĩnh viễn",
            "Sập hệ thống, bế tắc (deadlocks) hoặc vòng lặp vô tận",
            "Rò rỉ bộ nhớ (memory leaks) và cạn kiệt tài nguyên",
            "Triển khai mật mã học thiếu an toàn",
            "Mã hóa cứng thông tin bí mật hoặc khóa API (hardcoded secrets)"
          ]
        },
        {
          "category": "CHỨC NĂNG (FUNCTIONAL)",
          "severity": "P1-P2",
          "types": [
            "Lỗi logic (điều kiện sai, tính toán sai, lỗi sai lệch một đơn vị - off-by-one)",
            "Vấn đề quản lý trạng thái (race conditions, dữ liệu cũ, biến đổi trạng thái không an toàn)",
            "Sai lệch giao ước API (API contracts) hoặc ánh xạ request/response",
            "Thiếu sót hoặc kiểm thực dữ liệu đầu vào không đầy đủ",
            "Vi phạm luồng nghiệp vụ hoặc quy tắc kinh doanh",
            "Chuyển đổi dữ liệu hoặc tuần tự hóa sai",
            "Không tương thích kiểu dữ liệu hoặc ép kiểu không an toàn",
            "Xử lý ngoại lệ hoặc lan truyền lỗi không đúng"
          ]
        },
        {
          "category": "TÍCH HỢP (INTEGRATION)",
          "severity": "P2",
          "types": [
            "Gọi API bên ngoài sai cách hoặc endpoint lỗi thời",
            "Lỗi truy vấn cơ sở dữ liệu, cú pháp SQL hoặc sự cố N+1 query",
            "Lỗi xử lý hàng đợi tin nhắn (RabbitMQ, Kafka, SQS)",
            "Lỗi thao tác hệ thống tệp tin (phân quyền, path traversal)",
            "Sự cố giao tiếp mạng (hết thời gian chờ, cơ chế thử lại, connection pooling)",
            "Không nhất quán bộ đệm (cache) hoặc sự cố hủy cache",
            "Sử dụng sai thư viện bên thứ ba hoặc xung đột phiên bản"
          ]
        },
        {
          "category": "TRƯỜNG HỢP BIÊN (EDGE_CASES)",
          "severity": "P2-P3",
          "types": [
            "Truy xuất con trỏ Null/undefined/nil/None",
            "Xử lý mảng/danh sách rỗng",
            "Trường hợp biên giá trị 0 hoặc số âm",
            "Điều kiện ranh giới (giá trị số nguyên lớn nhất/nhỏ nhất, giới hạn độ dài chuỗi)",
            "Thiếu xử lý lỗi hoặc nuốt ngoại lệ âm thầm (swallowed exceptions)",
            "Thất bại trong logic quá thời gian chờ (timeout) và thử lại",
            "Xung đột truy cập đồng thời không có khóa (lock) thích hợp",
            "Tràn số trên (overflow) hoặc tràn số dưới (underflow) trong phép toán số học"
          ]
        },
        {
          "category": "CHẤT LƯỢNG MÃ NGUỒN (CODE_QUALITY)",
          "severity": "P3-P4",
          "types": [
            "Sử dụng các API đã lỗi thời (deprecated)",
            "Mã chết (dead code) hoặc các nhánh mã không bao giờ được thực thi",
            "Phụ thuộc vòng tròn (circular dependencies)",
            "Điểm nghẽn hiệu năng (thuật toán kém hiệu quả, thao tác dư thừa)",
            "Thiếu hoặc chú thích kiểu dữ liệu (type annotations) không chính xác",
            "Khuôn mẫu xử lý lỗi thiếu nhất quán",
            "Rò rỉ tài nguyên (con trỏ tệp, kết nối cơ sở dữ liệu, socket mạng)",
            "Ghi log không đúng chuẩn (lộ dữ liệu nhạy cảm, thiếu ngữ cảnh gỡ lỗi)"
          ]
        }
      ],
      "discovery_methods": [
        "Phân tích mã tĩnh bằng công cụ đặc thù theo ngôn ngữ",
        "Khớp mẫu (pattern matching) tìm kiếm các anti-patterns và code smells phổ biến",
        "Quét lỗ hổng bảo mật gói phụ thuộc (npm audit, pip-audit, bundle-audit, cargo audit)",
        "Phân tích luồng điều khiển và luồng dữ liệu",
        "Phát hiện mã chết và đoạn code không sử dụng",
        "Xác thực cấu hình đối chiếu với các thực hành tốt nhất",
        "Đối chiếu chéo tài liệu hướng dẫn với mã nguồn thực tế",
        "Rà soát mã nguồn tập trung vào an toàn bảo mật (security code review)"
      ]
    },
    {
      "phase": 3,
      "name": "Lập Tài Liệu Lỗi & Phân Loại Mức Độ Ưu Tiên",
      "bug_report_schema": {
        "bug_id": "Mã định danh tuần tự (BUG-001, BUG-002, v.v.)",
        "severity": {
          "type": "enum",
          "values": [
            "CRITICAL",
            "HIGH",
            "MEDIUM",
            "LOW"
          ],
          "description": "Mức độ nghiêm trọng của lỗi"
        },
        "category": {
          "type": "enum",
          "values": [
            "SECURITY",
            "FUNCTIONAL",
            "PERFORMANCE",
            "INTEGRATION",
            "CODE_QUALITY"
          ],
          "description": "Phân loại danh mục lỗi"
        },
        "location": {
          "files": [
            "Mảng đường dẫn tệp bị ảnh hưởng kèm số dòng"
          ],
          "component": "Tên Module / Dịch vụ / Tính năng",
          "function": "Tên hàm hoặc phương thức cụ thể"
        },
        "description": {
          "current_behavior": "Hành vi hiện tại đang bị lỗi hoặc sai lệch",
          "expected_behavior": "Hành vi kỳ vọng đúng đắn cần có",
          "root_cause": "Giải thích kỹ thuật về nguyên nhân gốc rễ gây ra lỗi"
        },
        "impact_assessment": {
          "user_impact": "Tác động đối với người dùng cuối (mất dữ liệu, rủi ro bảo mật, suy giảm trải nghiệm)",
          "system_impact": "Tác động đối với hệ thống (hiệu năng, độ ổn định, khả năng mở rộng)",
          "business_impact": "Tác động kinh doanh (tuân thủ pháp lý, doanh thu, danh tiếng, pháp lý)"
        },
        "reproduction": {
          "steps": [
            "Các bước chi tiết từng bước để tái hiện lỗi"
