          "discovered_by": "Công cụ hoặc phương pháp phát hiện",
          "cve_id": "Mã định danh CVE (nếu áp dụng)",
          "cwe_id": "Mã định danh CWE (nếu áp dụng)"
        }
      },
      "prioritization_matrix": {
        "criteria": [
          {
            "factor": "severity (mức độ nghiêm trọng)",
            "weight": 0.4,
            "scale": "CRITICAL=100, HIGH=70, MEDIUM=40, LOW=10"
          },
          {
            "factor": "user_impact (tác động người dùng)",
